insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('3b90d9b0-522a-581b-8cf2-e7d91dc2bc5d', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-1..O-2', null, 'Lieutenant — overview', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'FA 30 has no authorized/assigned lieutenants.', '95e90d586fa4763f5b6fd1d1cb72dbd547a767d62cbcd55f8a86c086894e3b66', 3, 3, null, 0, null, null, false, null),
  ('3dd17fab-122c-59d2-bd07-fd59cf463f20', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-3', null, 'Captain development — overview', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'The professional development objective for this phase is to serve as a staff officer developing tactical skills and expanding capabilities through developmental assignments.', '33cb6fa0dc64b25ff860e5f0e17eba3e672f3aa6b1b06f9959d7a6b4f353abbb', 3, 3, null, 1, null, null, false, null),
  ('2b0485e7-1be5-58e2-aea4-4ec96ce1b442', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'training', 'O-3', null, 'Captain development — Education', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'Completion of CCC and IOQC.', 'e5775cb9039ade1d5b6d03e65437828743272e602b5c6556567e369902176bb7', 3, 3, null, 2, null, null, false, null),
  ('4920451e-bd61-5291-8b92-7c94b53f4c59', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'assignments', 'O-3', null, 'Captain development — Assignments', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'All assignments are important to sustain a trained and ready Army. Assignments are based on the needs of the Army in accordance with HQDA manning guidance, the professional development needs of the officer, and the officer’s preference.
(a) Key developmental. Officers assessed into FA 30 should expect to rotate between KD positions at 1st IO Command, Division and multifunctional brigades in order to gain an operational perspective to prepare for future joint assignments.
(b) Broadening assignments. Broadening is accomplished across an officer’s full career through experiences and/or education in different organizational cultures and environments. The intent of broadening is to develop the capability to see, work, learn, and contribute outside each officer''s perspective, or individual level of understanding, for the betterment of both the officer and the institution. Broadening opportunities may vary in scope, responsibility, and developmental outcomes. These positions are typically self or branch nominative in nature and typically fall in four major categories listed below.
(1) Functional/institutional. These assignments are directly related to IO, but provide the opportunity to develop a wider range of knowledge and skills useful in an Army specific environment or a broader joint context. IO assignments include FORSCOM and Combat Training Centers.
(2) Academia and civilian enterprise. Opportunities not available for IO captains.', 'e6c947525b5f706542e55f8bdef05e7b39d4ed6b88eeaa406e99ee5818a676b8', 3, 3, null, 3, null, null, false, null),
  ('323da7da-7095-5428-a80f-ce8ce744d11a', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-3', null, 'Captain development — Joint/multinational', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'These joint assignments are related or unrelated to IO requiring routine interaction with JIIM organizations and personnel. IO opportunities include assignments at USCYBERCOM and STRATCOM.', 'd19d9c3a4f36f231aaa1c4df131e044e0d10b39d67dd7078b15a1d6e99fb1027', 3, 3, null, 4, null, null, false, null),
  ('4a1165fe-1dc4-517e-9e8d-0f0f34929667', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-3', null, 'Captain development — Interagency/intergovernmental', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'Opportunities not available for IO captains.
(3) Self-development. Captains should continue to gain an in-depth understanding of MDMP and concentrate on those critical IO tasks required to accomplish their wartime mission. This provides the foundation of knowledge required to effectively serve as a staff officer at the brigade or division level. Emphasis should be maintained on historical and current lessons learned as they apply to tactical and leadership challenges.
(4) Promotion. Normally an officer within a cohort year group enters the primary zone of consideration for major around the 9th year of service. Potential for continued service is demonstrated through intellectual, moral and physical characteristics to include character, warrior and service ethos, strategic leadership, leader attributes, team building, leading change, fitness and resiliency, education, experience, performance and demonstrated potential.', '85a1d21d08668fc7749cfb08a94ca3c443cb308c7b5fe81a094ef71a810b6506', 3, 3, null, 5, null, null, false, null),
  ('2cad0330-ed3b-50e0-9cca-3030d932a4da', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-4', null, 'Major development — overview', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'This phase, which generally encompasses the 10th to 17th years of service, expands the officer’s tactical and technical experience. As a result, the officer will develop as an IO staff officer with a comprehensive understanding of operations in a joint and expeditionary environment. FA 30 majors continue to develop their knowledge and understanding of the operational force by serving as a staff officer at division through ASCC. These assignments ensure FA 30 officers are prepared for increasingly complex, developmental assignments.', '9cb9ec807055cf38cf711b87e2c18e9239237a2bca431cebac33690f767e440b', 3, 3, null, 6, null, null, false, null),
  ('1749b4e2-dbea-5123-aaac-82be2db1b0e9', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'training', 'O-4', null, 'Major development — Education', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'All FA 30 majors must complete the IOQC and the U.S. Command and General Staff Officer Course, resident or nonresident, or a sister Service ILE course to be JPME I qualified. Majors will also be able to compete for attendance at SAMS, Training with Industry, and Advanced Civilian Schooling. Upon completion, selectees will serve a utilization tour.', '86d9395913d048aa1261a461dd6b6d623458753b159e26a997a8fcc487908d22', 3, 4, null, 7, null, null, false, null),
  ('b72de7db-1a50-5637-b08f-e8b171796594', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'assignments', 'O-4', null, 'Major development — Assignments', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'All assignments are important to sustain a trained and ready Army. Assignments are based on the needs of the Army in accordance with HQDA manning guidance, the professional development needs of the officer, and the officer’s preference.
(a) Key developmental. Positions that are fundamental to the development of IO officers include 1 st IO Command, Division, Corps and ASCC. In accordance with the CSA’s guidance, assignments with transition teams/provincial reconstruction teams are considered KD assignments.
(b) Broadening assignments. Broadening opportunities may vary in scope, responsibility and developmental outcomes and typically fall in four major categories listed below:
(1) Functional/institutional. Majors should view these assignments as directly or indirectly related to IO, but provide the opportunity to develop a wider range of knowledge and skills useful in an Army specific environment or a broader joint context. IO opportunities include assignments to special operations units, Asymmetric Warfare Group, Combined Arms Center (CAC), CTCs, HQDA, Ranger Regiment and ARCYBER.
(2) Academia and civilian enterprise. These assignments focus on civilian industry or within an education community of higher learning where the officer gains knowledge, skills, and abilities not generally obtained from organic experiences, training or education. IO opportunities include Training with Industry, fellowships and serving as an IO Instructor.', 'b18d5adb8d45fbf366ac1c70bca670dd821261771e7b6dbe05d92645c26f7816', 4, 4, null, 8, null, null, false, null),
  ('f884001b-23b7-5825-9b88-e7c07c37538d', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-4', null, 'Major development — Joint/multinational', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'These assignments are joint opportunities related or unrelated to IO that require routine interaction with JIIM organizations and personnel. IO opportunities include assignments at SMDC/ARSTRAT NATO, Joint Information Operations Warfare Center and combatant commands. While not every officer will receive an assignment in a qualifying joint assignment or serve a fellowship in a JIIM agency, the goal is to provide the maximum opportunity for FA 30 majors to receive JIIM experience. The JIIM assignments for FA 30 majors are dependent upon Army demands and position/fellowship availability.', 'b24261b0f02cedfa6c349b24c3b044cb347d1be2edd5dedec37f8b8e7af3a8c2', 4, 4, null, 9, null, null, false, null),
  ('a71bd0cd-f92a-5fc1-86c7-31239cdb8b39', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-4', null, 'Major development — Interagency/intergovernmental', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'These assignments are typically within U.S. Government agencies or outside DOD. IO opportunities include: State Department and Defense Intelligence Agency.
(3) Self Development. Self-development, consisting of individual study, research, professional reading, practice and self-assessment, is key to attain and sustain the degree of competency needed to perform varied missions.
(4) Promotion. Cohort year group officers are generally considered for promotion to lieutenant colonel in their 16 th year of service as they enter the primary zone of consideration. Potential for continued service is demonstrated through intellectual, moral and physical characteristics to include character, warrior and service ethos, strategic leadership, leader attributes, team building, leading change, fitness and resiliency, education, experience, performance and demonstrated potential.', '8102b55ac68c7cb96296625a3446bb2c719db033bf42b47a06c9bb4eb999984a', 4, 4, null, 10, null, null, false, null),
  ('25e594e7-5b7e-5f7e-a507-5336e328878e', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-5', null, 'Lieutenant colonel — overview', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'This phase, which generally occurs between the 17th and 22nd years of service, expands the officer’s tactical and operations skills and technical proficiency. As a result, the officer makes a greater contribution to the functional area and the Army.', '8d6b36b16158a806414b903018f5dc9da0102318638789ad89c4ccedccf9b057', 4, 4, null, 11, null, null, false, null),
  ('d6bd1c7b-b355-5acc-a0ef-83dc7c407f88', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'training', 'O-5', null, 'Lieutenant colonel — Education', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'The annual Senior Service College (SSC) selection board reviews the files of lieutenant colonels for SSC attendance. Officer must be ILE/JPME I qualified to be eligible for consideration. Resident attendance is at the U.S. Army War College, the Advanced Strategic Leadership Studies Program within the School of Advanced Studies at Fort Leavenworth, the Eisenhower School for National Security, the National War College, the College of International Security Affairs, the Joint Advanced Warfighting School, Inter-American Defense College other sister Service war colleges, resident fellowships at governmental agencies and academic institutions and approved foreign SSCs.', 'cf6da6591958a28bb9901b476cabeb6007e28fd456d95f7daa2b3148bce5124d', 4, 4, null, 12, null, null, false, null),
  ('81f3c6b1-0e7d-5ab8-92c8-c5679572efed', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'assignments', 'O-5', null, 'Lieutenant colonel — Assignments', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'All assignments are important to sustain a trained and ready Army. Assignments are based on the needs of the Army in accordance with HQDA manning guidance, the professional development needs of the officer, and the officer’s preference.
(a) Key developmental. Positions that are fundamental to the development of IO officers include staff officers at Army division, corps and ASCC headquarters. Lieutenant colonels have the opportunity to compete for command of 1st Battalion, 1st Information Operations Command.
(b) Broadening assignments. Broadening opportunities may vary in scope, responsibility, and developmental outcomes and typically fall in four major categories listed below:
(1) Functional/institutional. Lieutenant colonels should view these assignments as directly or indirectly related to IO, but provide the opportunity to develop a wider range of knowledge and skills useful in an Army specific environment or a broader joint context. IO assignments include CAC, CTCs, ARCYBER, and HQDA.
(2) Academia and civilian enterprise. These assignments focus on civilian industry or within an education community of higher learning where the officer gains knowledge, skills and abilities not generally obtained from organic experiences, training or education. Examples of IO assignments include Training with Industry, fellowships, and serving as an IO instructor.
(3). Joint/multinational. These are joint opportunities related, or unrelated to IO that require routine interaction with JIIM organizations and personnel. IO assignments include NATO, Joint Information Operations Warfare Center (JIOWC) and combatant commands. After completion of a 36 month tour of duty in a standard-Joint duty assignment list, officers will be awarded the 3A (Joint Duty Qualified) skill identifier.
(4). Interagency/intergovernmental. These assignments are typically within U.S. Government agencies or outside DOD.', '0fb6ae5c5d18b40b22fc342dbc34efc29b5be582e717353b65246d555eea156c', 4, 5, null, 13, null, null, false, null),
  ('d91c638a-839b-520f-9f21-57bff433bfd7', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'self_development', 'O-5', null, 'Lieutenant colonel — Self-development', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'During this phase, self-assessment, continuous learning, and perfecting mentoring and managerial skills are essential to officer development. The officer should continue to hone his or her combined arms warfighting skills and understanding of the joint operational environment. In addition, officers should continue to read books from the CSA’s professional reading list to improve critical thinking and understanding of the profession of arms.', '937dfd8af48d4f456871fdc60a98385477a7154e871d4d4ea0e03ad6262d2a24', 5, 5, null, 14, null, null, false, null),
  ('c1a2a403-fcf1-5cb5-ad34-8d293abfa753', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-5', null, 'Lieutenant colonel — Promotion', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'Cohort year group officers are normally considered for promotion to colonel in the primary zone in their 21st year of service. Potential for continued service is demonstrated through intellectual, moral and physical characteristics to include character, warrior and service ethos, strategic leadership, leader attributes, team building, leading change, fitness and resiliency, education, experience, performance and demonstrated potential.', '5eae4992aef693e3a822e72c4d73a87c839fb65b25c7efee2acf21ddc6ced130', 5, 5, null, 15, null, null, false, null),
  ('62280001-f59a-5431-b63b-c53432155a51', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-6', null, 'Colonel development — overview', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'The professional development objective for this phase is sustainment of warfighting, training, technical and staff skills, along with utilization of leadership, organizational and executive talents. The objective of FA 30 colonel professional development is greater contribution to IO and the Army.', 'f67f1af17c82616dcb5a6638c5b312a55fdbb45889bf0ba40121cb698e766d05', 5, 5, null, 16, null, null, false, null),
  ('7d69911c-3117-5104-a8e7-480056896b67', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'training', 'O-6', null, 'Colonel development — Education', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'Completion of SSC, either resident or nonresident. Successful completion of JPME II is desired.', '80c97dc2bce984896c55b73faf3f3387d31211e3a255c3ee5de6653b3a4f9c4c', 5, 5, null, 17, null, null, false, null),
  ('15aaddad-a263-5178-8097-13b103b3020c', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'assignments', 'O-6', null, 'Colonel development — Assignments', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'All assignments are important to sustain a trained and ready Army. Assignments are based on the needs of the Army in accordance with HQDA manning guidance, the professional development needs of the officer, and the officer’s preference.
(a) Key developmental. Positions that are fundamental to the development of IO officers include IO positions within Army Corps and ASCC. FA 30 colonels may compete to command 1st Information Operations Command.
(b) Broadening assignments. Broadening opportunities may vary in scope, responsibility, and developmental outcomes and typically fall in four major categories listed below:
(1) Functional/institutional. Colonels should view these assignments as directly or indirectly related to IO, but provide the opportunity to develop a wider range of knowledge and skills useful in an Army specific environment or a broader joint context. Examples of these IO assignments include HQDA.
(2) Academia and civilian enterprise. These assignments focus on civilian industry or within an education community of higher learning where the officer gains knowledge, skills and abilities not generally obtained from organic experiences, training or education. Examples of IO assignments include Army War College Instructor or Proponent Director.', '4548b3229db0cbd28876f2d1b5dc73ea5981e8662ee4ce275069ab39a0c6e9a5', 5, 6, null, 18, null, null, false, null),
  ('07a21719-ab12-5c4d-aa11-2d34c43baf80', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-6', null, 'Colonel development — Joint/multinational', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'These assignments are joint opportunities related or unrelated to IO that require routine interaction with JIIM organizations and personnel. FA 30 officers are encouraged to seek joint education and duty assignments to achieve joint status. IO opportunities include NATO, JIOWC and combatant commands.', '7f177a42c46e05251883b4f8fa6b8abecf8ac896a18de21a3d1ac4a6d3d373bd', 6, 6, null, 19, null, null, false, null),
  ('6a739ac0-bb78-529f-b70d-e11d2701c953', '5565602f-d758-5b14-8dcb-350aebc19426', 'Army', 'officer', '30A', 'INFORMATION OPERATIONS OFFICER', 'development', 'O-6', null, 'Colonel development — Interagency/intergovernmental', 'Information Operations Functional Area (FA30) career pamphlet, DA PAM 600-3 chapter (1 June 2017)', 'These opportunities are more politically and policy oriented. Examples include agencies outside DOD.
(3) Self-development. FA 30 colonels must maintain their core skills and remain current on all changes that affect the Soldiers they manage. Officers also need to stay current on industry trends through trade associations and journals, and by participating in DOD and industry sponsored forums.
(4) Promotion. Promotion to general officer is managed separately and is beyond the scope of this pamphlet.', '70557aeb6773221c28500fcc70914ed42a4a38ad0d9e1d18d38f18f7fcf86752', 6, 6, null, 20, null, null, false, null);
